DROP TABLE IF EXISTS "mxpress_schedules";
DROP TABLE IF EXISTS "mxpress_trains";

CREATE TABLE "mxpress_trains" (
    "train_id"                 integer GENERATED BY DEFAULT AS IDENTITY,
    "train_name"               text NOT NULL,
    "origin"                   text,
    "destination"              text,
    "scheduled_departure_time" timestamp,
    "scheduled_arrival_time"   timestamp,
    "inventory"                text,
    CONSTRAINT "pkey_trains" PRIMARY KEY ("train_id")
);

CREATE TABLE "mxpress_schedules" (
    "train_id"    integer NOT NULL,
    "board_point" text NOT NULL,
    "off_point"   text NOT NULL,
    "travel_date" date NOT NULL,
    "timing"      timestamp NOT NULL,
    "fare_level"  text,
    CONSTRAINT "pkey_schedules" PRIMARY KEY ("train_id"),
    CONSTRAINT "fkey_schedules" FOREIGN KEY ("train_id")
        REFERENCES "mxpress_trains" ("train_id")
        ON DELETE CASCADE
);